import React, { useState } from "react";
import "./SpendingPriority.css";

function SpendingPriority({ onNext }) {

  const [selected, setSelected] = useState([]);

  const categories = [
    "Food & Dining",
    "Groceries",
    "Transport",
    "Shopping",
    "Entertainment",
    "Utilities",
    "Health",
    "Education"
  ];

  const toggleCategory = (cat) => {
    if (selected.includes(cat)) {
      setSelected(selected.filter(item => item !== cat));
    } else {
      setSelected([...selected, cat]);
    }
  };

  const handleNext = () => {
    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) return;

    // ✅ SAVE PER USER
    localStorage.setItem(
      `categories_${user.email}`,
      JSON.stringify(selected)
    );

    onNext();
  };

  return (
    <div className="spending-page">
      <h2>Select where you spend most</h2>

      <div className="category-grid">
        {categories.map((cat, i) => (
          <div
            key={i}
            className={`category-card ${selected.includes(cat) ? "active" : ""}`}
            onClick={() => toggleCategory(cat)}
          >
            {cat}
          </div>
        ))}
      </div>

      <button onClick={handleNext}>
        Continue
      </button>
    </div>
  );
}

export default SpendingPriority;
